from ta_emss.utilities.ex_terminator_rpc.err_transport import ErrRemoteEndpointDisconnected
from ta_emss.utilities.ex_terminator_rpc.transport_medium import AsyncTCPTransportMedium
from ta_emss.utilities.ex_terminator_rpc.err_transport import ErrTransportTimeout
from ta_emss.utilities.ex_terminator_rpc.rpc_call_wraped import RpcCall
from ta_emss.utilities.ex_terminator_rpc.json_client import JsonClient
from time import sleep, time
import subprocess
import logging
import pexpect
import os


PORT = 1121


