class ExTerminatorClient():
    def __init__(self, host):
        self.logger = logging.getLogger('ExTerminatorClient')
        self.tcp_conn = AsyncTCPTransportMedium(port=PORT, host=host, logger=self.logger)
        self.rpc_conn = JsonClient("conn1", self.tcp_conn)
        self.rpc_call = RpcCall(self.rpc_conn, self.logger).call
        self.rpc_conn._activated_transport_encoding = "netstring"
        self.timeout = 600
        self.is_open = False
        self._ex_terminator_proceess = None
        self._started_internally = None
        # self._open_rcp_conn()

    def _call(self, data, log_msg):
        try:
            return self.rpc_call(data=data, log_msg=log_msg)
        except ErrTransportTimeout:
            self.logger.warning("Request {} has timed out".format(data))
            raise
        except (ErrRemoteEndpointDisconnected,) as err:
            # todo: some sleep needed?
            self._restart_conn()
            self.logger.warning("{}. Connection restarted.".format(err))
            return self.rpc_call(data=data, log_msg=log_msg)

    def _open_rcp_conn(self, timeout=5, early=False):
        start_time = time()
        while True:
            try:
                self.rpc_conn.open_connection()
                break
            except Exception as err:  # nopep8
                if early and isinstance(err, ConnectionRefusedError):
                    raise ExTermEarlyConnError("ExTerminator process is not running or not responding.")
                elif time() - start_time > timeout:
                    if isinstance(self._ex_terminator_proceess, subprocess.Popen):
                        return_code = self._ex_terminator_proceess.poll()
                        if return_code is not None and return_code != 0:
                            raise RuntimeError("ExTerminator process has exited with code {}".format(return_code))
                    raise RuntimeError("ExTerminator process is not running or not responding.")
            sleep(0.5)

    def _restart_conn(self):
        sleep(2)
        del self.rpc_conn
        self.rpc_conn = JsonClient("conn1", self.tcp_conn)
        self.rpc_conn._activated_transport_encoding = "netstring"
        self._open_rcp_conn()

    def open_connection(self, early=False):
        if self.is_open:
            return
        self._open_rcp_conn(early=early)
        self.is_open = True

    def close(self):
        """Close callback on test finish"""
        pass

    def setup_exterminator(self, config, amfs, vdus, gnbs, enbs, ex_terminator_options=None):
        env = os.environ.copy()
        if ex_terminator_options:
            if ex_terminator_options.get("telemetry_enabled?", "true"):
                env["TELEMETRY_ENABLED"] = "true"
            if ex_terminator_options.get('bts_build'):
                env["BTS_BUILD"] = str("essa")
            if ex_terminator_options.get('ta_emss_build'):
                env["TA_EMSS_BUILD"] = str(ex_terminator_options['ta_emss_build'])
            else:
                env["TELEMETRY_ENABLED"] = "false"

        try:
            self.open_connection(early=True)
        except ExTermEarlyConnError:
            ex_terminator_bin_file_path = '/opt/esim-xterminator/ex_terminator/bin/ex_terminator'
            self._install_esim_xterminator_if_needed(ex_terminator_bin_file_path)
            self._ex_terminator_proceess = subprocess.Popen([ex_terminator_bin_file_path, 'start'], env=env)
            self._started_internally = True
            self.open_connection()
            ex_terminator_options['client_python_pid'] = os.getpid()
        data={'python_input_config': config, 'amfs': amfs, 'vdus': vdus, 'gnbs': gnbs, 'enbs': enbs,
              'ex_terminator_options': ex_terminator_options}
        result = self._call(data, log_msg='python_input_config')
        return result

    def _install_esim_xterminator_if_needed(self, ex_terminator_bin_file_path):
        if not os.path.exists(ex_terminator_bin_file_path):
            print('ExTerminator binary not found, installing esim-xterminator')
            child = pexpect.spawn('sudo apt-get -y install esim-xterminator')
            child.expect(pexpect.EOF, timeout=600)
            result = child.before.decode() if hasattr(child.before, 'decode') else str(child.before)
            if not os.path.exists(ex_terminator_bin_file_path):
                print('esim-xterminator installation failed')
                raise RuntimeError(f'esim-xterminator installation failed: {result}')
            self.logger.debug(f"apt-get install output: {result}")
            print('esim-xterminator installation succeeded')

    def ensure_connection(func):
        def wrapper(self, *args, **kwargs):
            self.open_connection()
            return func(self, *args, **kwargs)
        return wrapper

    @ensure_connection
    def start(self, protocol):
        return self._call(data=f'start_{protocol}', log_msg=f'start_{protocol}')

    @ensure_connection
    def stop(self, protocol):
        return self._call(data=f'stop_{protocol}', log_msg=f'stop_{protocol}')

    def stop_app(self):
        try:
            self.rpc_conn.close_connection()
            del self.rpc_conn
            if self._started_internally:
                child = pexpect.spawn('/opt/esim-xterminator/ex_terminator/bin/ex_terminator stop')
                child.expect(pexpect.EOF, timeout=600)
                return True
            else:
                print("Exterminator started externally - won't be stopped")
                return False
        except AttributeError:
            return False


class ExTermEarlyConnError(RuntimeError):
    pass
